#define FG_CONV_L20_NO_MAIN
#include "rtx_oracle.cpp"
#include "custom_block1_bot1_contract.h"
namespace{namespace c=fg_custom_block1_bot1;struct Params{CUdeviceptr w,b;std::uint32_t oc,kh,kw,ic;CUdeviceptr l0,l1,l2,s0,s1,s2;std::uint32_t ib,ih,iw,is;CUdeviceptr out;std::uint32_t s0b,s0h,s0w,s0s,s1b,s1h,s1w,s1s,s2b,s2h,s2w,s2s;};static_assert(sizeof(Params)==152);
void Rec(const std::filesystem::path&p,const std::string&id,std::uint8_t poison,const std::vector<std::uint8_t>&w0,const std::vector<std::uint8_t>&b0,const std::array<std::vector<std::uint8_t>,6>&i0,const std::vector<std::uint8_t>&w1,const std::vector<std::uint8_t>&b1,const std::array<std::vector<std::uint8_t>,6>&i1,const std::vector<std::uint8_t>&out,std::size_t mm,std::size_t cc){std::ofstream s(p);bool pass=mm==0&&cc==0;s<<"{\n  \"schema\": \"neuralstudio.fg.custom-block1-bot1-run.v1\",\n  \"backend\": \"rtx-cuda-driver\",\n  \"run_id\": \""<<id<<"\",\n  \"process_id\": "<<GetCurrentProcessId()<<",\n  \"poison_byte\": "<<unsigned(poison)<<",\n  \"trace_launch_token\": \"launch-000083\",\n  \"module_token\": 66,\n  \"module_bytes\": "<<c::kModuleBytes<<",\n  \"module_sha256\": \""<<c::kModuleSha256<<"\",\n  \"function_name\": \"custom_block1_conv_bot1_hf_kernel\",\n  \"grid\": [40, 46, 3],\n  \"block\": [32, 8, 1],\n  \"packed_parameter_bytes\": 152,\n  \"weight_source_token\": 202,\n  \"bias_source_token\": 204,\n  \"model_manifest_sha256\": \""<<c::kManifestSha256<<"\",\n  \"weight_pre_sha256\": \""<<Sha256(w0)<<"\",\n  \"weight_post_sha256\": \""<<Sha256(w1)<<"\",\n  \"bias_pre_sha256\": \""<<Sha256(b0)<<"\",\n  \"bias_post_sha256\": \""<<Sha256(b1)<<"\",\n  \"input_generator\": \"splitmix64-fg-custom-block1-bot1-v1\",\n  \"input_pre_sha256\": [\""<<Sha256(i0[0])<<"\", \""<<Sha256(i0[1])<<"\", \""<<Sha256(i0[2])<<"\", \""<<Sha256(i0[3])<<"\", \""<<Sha256(i0[4])<<"\", \""<<Sha256(i0[5])<<"\"],\n  \"input_post_sha256\": [\""<<Sha256(i1[0])<<"\", \""<<Sha256(i1[1])<<"\", \""<<Sha256(i1[2])<<"\", \""<<Sha256(i1[3])<<"\", \""<<Sha256(i1[4])<<"\", \""<<Sha256(i1[5])<<"\"],\n  \"output_sha256\": \""<<Sha256(out)<<"\",\n  \"output_bytes\": "<<out.size()<<",\n  \"input_mismatched_bytes\": "<<mm<<",\n  \"canary_mismatched_bytes\": "<<cc<<",\n  \"external_model_files_opened\": true,\n  \"expected_output_file_opened\": false,\n  \"address_fields_recorded\": false,\n  \"result\": \""<<(pass?"pass":"fail")<<"\"\n}\n";}}
int main(int argc,char**v){if(argc!=7)return 2;try{auto mod=Read(v[1]),w0=Read(v[2]),b0=Read(v[3]);if(mod.size()!=c::kModuleBytes||Sha256(mod)!=c::kModuleSha256||w0.size()!=c::kWeightBytes||Sha256(w0)!=c::kWeightSha256||b0.size()!=c::kBiasBytes||Sha256(b0)!=c::kBiasSha256)throw std::runtime_error("identity");char*e=nullptr;auto q=strtoul(v[6],&e,16);if(e==v[6]||*e||q>255)throw std::runtime_error("poison");auto poison=std::uint8_t(q);std::filesystem::path dir=v[4];std::filesystem::create_directories(dir);auto i0=c::Inputs();Check(cuInit(0),"init");CUdevice d;Check(cuDeviceGet(&d,0),"dev");CUcontext x;Check(cuDevicePrimaryCtxRetain(&x,d),"ctx");Check(cuCtxSetCurrent(x),"set");CUmodule m;Check(cuModuleLoadData(&m,mod.data()),"module");CUfunction f;Check(cuModuleGetFunction(&f,m,"custom_block1_conv_bot1_hf_kernel"),"fn");GuardedDeviceBuffer w,b,l0,l1,l2,s0,s1,s2,out;w.Allocate(c::kWeightBytes);b.Allocate(c::kBiasBytes);l0.Allocate(c::kLatentBytes);l1.Allocate(c::kLatentBytes);l2.Allocate(c::kLatentBytes);s0.Allocate(c::kSkip0Bytes);s1.Allocate(c::kSkip1Bytes);s2.Allocate(c::kSkip2Bytes);out.Allocate(c::kOutputBytes);Check(cuMemcpyHtoD(w.payload(),w0.data(),w0.size()),"w");Check(cuMemcpyHtoD(b.payload(),b0.data(),b0.size()),"b");Check(cuMemcpyHtoD(l0.payload(),i0[0].data(),i0[0].size()),"l0");Check(cuMemcpyHtoD(l1.payload(),i0[1].data(),i0[1].size()),"l1");Check(cuMemcpyHtoD(l2.payload(),i0[2].data(),i0[2].size()),"l2");Check(cuMemcpyHtoD(s0.payload(),i0[3].data(),i0[3].size()),"s0");Check(cuMemcpyHtoD(s1.payload(),i0[4].data(),i0[4].size()),"s1");Check(cuMemcpyHtoD(s2.payload(),i0[5].data(),i0[5].size()),"s2");Check(cuMemsetD8(out.payload(),poison,c::kOutputBytes),"out");Params p{w.payload(),b.payload(),8,3,3,16,l0.payload(),l1.payload(),l2.payload(),s0.payload(),s1.payload(),s2.payload(),1,184,320,16,out.payload(),1,368,640,4,1,368,640,1,1,368,640,3};std::size_t n=sizeof(p);void*extra[]={CU_LAUNCH_PARAM_BUFFER_POINTER,&p,CU_LAUNCH_PARAM_BUFFER_SIZE,&n,CU_LAUNCH_PARAM_END};Check(cuLaunchKernel(f,40,46,3,32,8,1,0,nullptr,nullptr,extra),"launch");Check(cuCtxSynchronize(),"sync");auto wg=w.ReadAll(),bg=b.ReadAll(),l0g=l0.ReadAll(),l1g=l1.ReadAll(),l2g=l2.ReadAll(),s0g=s0.ReadAll(),s1g=s1.ReadAll(),s2g=s2.ReadAll(),og=out.ReadAll();auto w1=Payload(wg,c::kWeightBytes),b1=Payload(bg,c::kBiasBytes);std::array<std::vector<std::uint8_t>,6>i1={Payload(l0g,c::kLatentBytes),Payload(l1g,c::kLatentBytes),Payload(l2g,c::kLatentBytes),Payload(s0g,c::kSkip0Bytes),Payload(s1g,c::kSkip1Bytes),Payload(s2g,c::kSkip2Bytes)};auto o=Payload(og,c::kOutputBytes);std::size_t mm=Mismatches(w0,w1)+Mismatches(b0,b1);for(int j=0;j<6;++j)mm+=Mismatches(i0[j],i1[j]);auto can=CanaryMismatches(wg,c::kWeightBytes)+CanaryMismatches(bg,c::kBiasBytes)+CanaryMismatches(l0g,c::kLatentBytes)+CanaryMismatches(l1g,c::kLatentBytes)+CanaryMismatches(l2g,c::kLatentBytes)+CanaryMismatches(s0g,c::kSkip0Bytes)+CanaryMismatches(s1g,c::kSkip1Bytes)+CanaryMismatches(s2g,c::kSkip2Bytes)+CanaryMismatches(og,c::kOutputBytes);Rec(dir/"run-receipt.json",v[5],poison,w0,b0,i0,w1,b1,i1,o,mm,can);Write(dir/"output.bin",o);bool pass=mm==0&&can==0;std::cout<<"output_sha256="<<Sha256(o)<<"\nresult="<<(pass?"pass":"fail")<<'\n';return pass?0:3;}catch(const std::exception&e){std::cerr<<"error="<<e.what()<<'\n';return 1;}}
